import { createTestContext } from '../../../../test-utils'
import { Diagnostic, path } from '@servicenow/sdk-build-core'

describe('ForEach Diagnostics', () => {
    const ctx = createTestContext({ rootDir: path.resolve(__dirname, 'project') })
    beforeAll(() => ctx.initialize())
    afterEach(() => ctx.cleanup())
    describe('ForEach - Array Type Validation', () => {
        test('should error when config missing $id', async () => {
            const project = ctx.createProject()
            const file = project.addFile({
                path: 'foreach-missing-id.now.ts',
                content: `
import '@servicenow/sdk/global'
import { Flow, wfa, trigger, action } from '@servicenow/sdk/automation'

Flow(
    {
        $id: Now.ID['test_flow'],
        name: 'Test Flow',
    },
    wfa.trigger(
        trigger.record.created,
        { $id: Now.ID['test_trigger'] },
        {
            table: 'incident',
            condition: '',
        }
    ),
    (params) => {
        const lookupRecords = wfa.action(
            action.lookupRecords,
            { $id: Now.ID['lookup_action'] },
            {
                table: 'incident',
                conditions: [],
            }
        )

        // Invalid: config without $id
        wfa.flowLogic.forEach(
            lookupRecords.records,
            {} as any,
            (item) => {
                console.log('in loop')
            }
        )
    }
)
                `,
            })

            const diagnostics = await file.getDiagnostics()
            const error = diagnostics.find(
                (d) => d.message === 'ForEach: Second argument (config) must be an object with valid $id property'
            )
            expect(error).toBeDefined()
            expect(error?.level).toBe(Diagnostic.Level.Error)
        })

        test('should error with only 1 argument', async () => {
            const project = ctx.createProject()
            const file = project.addFile({
                path: 'foreach-1-arg.now.ts',
                content: `
import '@servicenow/sdk/global'
import { Flow, wfa, trigger, action } from '@servicenow/sdk/automation'

Flow(
    {
        $id: Now.ID['test_flow'],
        name: 'Test Flow',
    },
    wfa.trigger(
        trigger.record.created,
        { $id: Now.ID['test_trigger'] },
        {
            table: 'incident',
            condition: '',
        }
    ),
    (params) => {
        const lookupRecords = wfa.action(
            action.lookupRecords,
            { $id: Now.ID['lookup_action'] },
            {
                table: 'incident',
                conditions: [],
            }
        )

        // Invalid: only 1 argument
        wfa.flowLogic.forEach(lookupRecords.records as any)
    }
)
                `,
            })

            const diagnostics = await file.getDiagnostics()
            const error = diagnostics.find(
                (d) => d.message === 'ForEach requires 2-3 arguments (items, config, optional body), but received 1'
            )
            expect(error).toBeDefined()
            expect(error?.level).toBe(Diagnostic.Level.Error)
        })

        test('should error with 4 arguments', async () => {
            const project = ctx.createProject()
            const file = project.addFile({
                path: 'foreach-4-args.now.ts',
                content: `
import '@servicenow/sdk/global'
import { Flow, wfa, trigger, action } from '@servicenow/sdk/automation'

Flow(
    {
        $id: Now.ID['test_flow'],
        name: 'Test Flow',
    },
    wfa.trigger(
        trigger.record.created,
        { $id: Now.ID['test_trigger'] },
        {
            table: 'incident',
            condition: '',
        }
    ),
    (params) => {
        const lookupRecords = wfa.action(
            action.lookupRecords,
            { $id: Now.ID['lookup_action'] },
            {
                table: 'incident',
                conditions: [],
            }
        )

        // Invalid: 4 arguments
        wfa.flowLogic.forEach(
            lookupRecords.records,
            { $id: Now.ID['foreach1'] },
            (item) => {},
            'extra_arg' as any
        )
    }
)
                `,
            })

            const diagnostics = await file.getDiagnostics()
            const error = diagnostics.find(
                (d) => d.message === 'ForEach requires 2-3 arguments (items, config, optional body), but received 4'
            )
            expect(error).toBeDefined()
            expect(error?.level).toBe(Diagnostic.Level.Error)
        })

        test('should NOT error with valid array types', async () => {
            const project = ctx.createProject()
            const file = project.addFile({
                path: 'foreach-valid-arrays.now.ts',
                content: `
import '@servicenow/sdk/global'
import { Flow, wfa, trigger, action } from '@servicenow/sdk/automation'

Flow(
    {
        $id: Now.ID['test_flow'],
        name: 'Test Flow',
    },
    wfa.trigger(
        trigger.record.created,
        { $id: Now.ID['test_trigger'] },
        {
            table: 'incident',
            condition: '',
        }
    ),
    (params) => {
        const lookupRecords = wfa.action(
            action.lookupRecords,
            { $id: Now.ID['lookup_action'] },
            {
                table: 'incident',
                conditions: [],
            }
        )

        // Valid: array.record type
        wfa.flowLogic.forEach(
            lookupRecords.records,
            { $id: Now.ID['foreach1'] },
            (item) => {
                console.log('processing record')
            }
        )
    }
)
                `,
            })

            const diagnostics = await file.getDiagnostics()
            const error = diagnostics.find((d) => d.message.includes('array') && d.message.includes('type'))
            expect(error).toBeUndefined()
        })
    })
})
